import { Pool, PoolConfig } from 'pg';
import { z } from 'zod';

/**
 * Configuration schema for the PostgreSQL connection pool.
 * Enforces production-grade validation constraints.
 */
const PostgresConfigSchema = z.object({
  DB_URL: z.string().url(),
  DB_POOL_MIN: z.preprocess((val) => Number(val), z.number().int().positive()),
  DB_POOL_MAX: z.preprocess((val) => Number(val), z.number().int().positive()),
}).refine((data) => data.DB_POOL_MIN <= data.DB_POOL_MAX, {
  message: "DB_POOL_MIN cannot be greater than DB_POOL_MAX",
  path: ["DB_POOL_MIN"],
});

/**
 * Interface for pool statistics monitoring.
 */
export interface PoolStats {
  totalCount: number;
  idleCount: number;
  waitingCount: number;
}

/**
 * PostgresPoolManager handles the lifecycle of the database connection pool.
 * Implements a singleton pattern for application-wide connection management
 * in a high-throughput, event-sourced fraud detection engine.
 */
export class PostgresPoolManager {
  private static instance: PostgresPoolManager;
  private pool: Pool;
  private initialized: boolean = false;

  private constructor() {
    const rawConfig = {
      DB_URL: process.env.DB_URL,
      DB_POOL_MIN: process.env.DB_POOL_MIN,
      DB_POOL_MAX: process.env.DB_POOL_MAX,
    };

    const result = PostgresConfigSchema.safeParse(rawConfig);
    if (!result.success) {
      throw new Error(`Postgres Configuration Error: ${JSON.stringify(result.error.format())}`);
    }

    // Security constraint: Production environments MUST use SSL/TLS
    if (process.env.NODE_ENV === 'production' && !process.env.DB_URL?.includes('sslmode=verify-full')) {
      throw new Error('Insecure database connection detected: SSL/TLS with verify-full is mandatory in production.');
    }

    const config: PoolConfig = {
      connectionString: result.data.DB_URL,
      min: result.data.DB_POOL_MIN,
      max: result.data.DB_POOL_MAX,
      connectionTimeoutMillis: 5000,
      idleTimeoutMillis: 30000,
    };

    this.pool = new Pool(config);

    // Register error listener for robust operational monitoring
    this.pool.on('error', (err, client) => {
      console.error(JSON.stringify({
        level: 'error',
        message: 'Unexpected error on idle client',
        error: err.message,
        stack: err.stack,
        context: 'PostgresPoolManager'
      }));
    });
  }

  /**
   * Initializes the pool and performs a connectivity health check.
   * Provides a fail-fast mechanism for the persistence layer.
   */
  public async initialize(): Promise<void> {
    if (this.initialized) return;

    try {
      const client = await this.pool.connect();
      try {
        await client.query('SELECT 1');
      } finally {
        client.release();
      }
      this.initialized = true;
    } catch (err) {
      throw new Error(`Postgres health check failed during initialization: ${err instanceof Error ? err.message : String(err)}`);
    }
  }

  /**
   * Returns the singleton instance of PostgresPoolManager.
   */
  public static getInstance(): PostgresPoolManager {
    if (!PostgresPoolManager.instance) {
      PostgresPoolManager.instance = new PostgresPoolManager();
    }
    return PostgresPoolManager.instance;
  }

  /**
   * Provides access to the underlying node-postgres Pool.
   */
  public getPool(): Pool {
    return this.pool;
  }

  /**
   * Returns current pool statistics for observability purposes.
   * Can be mapped to Prometheus metrics.
   */
  public getStats(): PoolStats {
    return {
      totalCount: this.pool.totalCount,
      idleCount: this.pool.idleCount,
      waitingCount: this.pool.waitingCount,
    };
  }

  /**
   * Redacted configuration logging for security compliance.
   * Ensures credentials are not exposed in logs.
   */
  public logConfiguration(): void {
    const dbUrl = process.env.DB_URL || '';
    // Redact password part of the connection string
    const redactedUrl = dbUrl.replace(/:([^@]+)@/, ':****@');
    console.info(JSON.stringify({
      level: 'info',
      message: 'Postgres connection pool configured',
      url: redactedUrl
    }));
  }
}

import { PoolClient } from 'pg';
import { Registry, Histogram } from 'prom-client';
import { PostgresPoolManager } from './client';
import { CryptoValidator } from '../../../core/domain_models/security/crypto-validator.service';
import { MessageEnvelope } from '../../../core/domain_models/messaging/event-envelope.messaging';
import { Transaction } from '../../../core/domain_models/definitions/transaction.interface';
import {
  OptimisticConcurrencyError,
  IntegrityViolationError,
  ConnectionError,
} from './errors';

/**
 * EventRepository implementation for PostgreSQL-backed append-only event store.
 * Provides atomic append and versioned loading operations with cryptographic integrity checks.
 */
export class EventRepository<T extends Transaction> {
  private readonly poolManager: PostgresPoolManager;
  private readonly cryptoValidator: CryptoValidator;

  // Performance metrics
  private readonly sqlExecutionDuration: Histogram<string>;
  private readonly cryptoVerificationDuration: Histogram<string>;

  constructor(registry: Registry) {
    this.poolManager = PostgresPoolManager.getInstance();
    this.cryptoValidator = CryptoValidator.getInstance();

    this.sqlExecutionDuration = new Histogram({
      name: 'event_store_sql_execution_seconds',
      help: 'Duration of SQL operations in seconds',
      registers: [registry],
      labelNames: ['operation'],
    });

    this.cryptoVerificationDuration = new Histogram({
      name: 'event_store_crypto_verification_seconds',
      help: 'Duration of cryptographic verification in seconds',
      registers: [registry],
    });
  }

  /**
   * Appends a new event to the stream for a given aggregate.
   * Enforces optimistic concurrency and transactional integrity.
   */
  public async append(aggregateId: string, event: MessageEnvelope<T>, version: bigint): Promise<void> {
    const client = await this.acquireClient();
    const start = process.hrtime.bigint();

    try {
      await client.query('BEGIN TRANSACTION ISOLATION LEVEL SERIALIZABLE');

      // Check current version for optimistic concurrency
      const { rows } = await client.query(
        'SELECT version FROM events WHERE aggregate_id = $1 ORDER BY version DESC LIMIT 1 FOR UPDATE',
        [aggregateId]
      );

      const currentVersion = rows.length > 0 ? BigInt(rows[0].version) : 0n;
      if (version !== currentVersion + 1n) {
        throw new OptimisticConcurrencyError(aggregateId, version, currentVersion + 1n);
      }

      await client.query(
        `INSERT INTO events (aggregate_id, version, event_type, payload, signature, created_at)
         VALUES ($1, $2, $3, $4, $5, NOW())`,
        [
          aggregateId,
          version.toString(),
          event.payload.type,
          JSON.stringify(event.payload),
          event.signature,
        ]
      );

      await client.query('COMMIT');
      this.recordDuration(this.sqlExecutionDuration, 'append', start);
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    } finally {
      client.release();
    }
  }

  /**
   * Loads the event stream for a specific aggregate ID.
   * Performs cryptographic verification on every loaded event.
   */
  public async load(aggregateId: string): Promise<MessageEnvelope<T>[]> {
    const client = await this.acquireClient();
    const start = process.hrtime.bigint();

    try {
      const { rows } = await client.query(
        'SELECT * FROM events WHERE aggregate_id = $1 ORDER BY version ASC',
        [aggregateId]
      );

      const envelopes: MessageEnvelope<T>[] = [];

      for (const row of rows) {
        const envelope: MessageEnvelope<T> = {
          metadata: {
            schemaVersion: 'v1.0',
            createdAtNs: BigInt(new Date(row.created_at).getTime() * 1_000_000),
            provenanceTrace: 'db_load',
          },
          payload: row.payload as T,
          signature: row.signature,
        };

        // Cryptographic verification
        const cryptoStart = process.hrtime.bigint();
        const dataToVerify = JSON.stringify({ metadata: envelope.metadata, payload: envelope.payload });
        const isValid = await this.cryptoValidator.verify(dataToVerify, envelope.signature);
        this.recordDuration(this.cryptoVerificationDuration, 'verify', cryptoStart);

        if (!isValid) {
          throw new IntegrityViolationError(aggregateId, row.event_id, 'Cryptographic signature verification failed');
        }

        envelopes.push(envelope);
      }

      this.recordDuration(this.sqlExecutionDuration, 'load', start);
      return envelopes;
    } finally {
      client.release();
    }
  }

  private async acquireClient(): Promise<PoolClient> {
    try {
      return await this.poolManager.getPool().connect();
    } catch (err) {
      throw new ConnectionError(err instanceof Error ? err.message : 'Unknown connection error', this.poolManager.getStats());
    }
  }

  private recordDuration(histogram: Histogram<string>, label: string, start: bigint): void {
    const end = process.hrtime.bigint();
    const duration = Number(end - start) / 1e9;
    histogram.labels(label).observe(duration);
  }
}

-- Event Store Schema DDL
-- This script defines the immutable transaction log for the fraud detection engine.
-- Designed for high throughput and consistent event sourcing.

BEGIN;

-- Enable UUID extension if not already available
CREATE EXTENSION IF NOT EXISTS "uuid-ossp";

-- Main events table storing immutable transaction logs.
-- Append-only access policy should be enforced at the database role level.
CREATE TABLE IF NOT EXISTS events (
    event_id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    aggregate_id UUID NOT NULL,
    version BIGINT NOT NULL,
    event_type VARCHAR(255) NOT NULL,
    payload JSONB NOT NULL,
    signature TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,

    -- Optimistic Concurrency Control: Ensures each aggregate has a unique
    -- version sequence, preventing race conditions on updates.
    CONSTRAINT unique_aggregate_version UNIQUE (aggregate_id, version)
);

-- Indexing Strategy:

-- 1. GIN index on 'payload' for efficient querying of JSONB data.
-- This allows fast retrieval based on nested fields within the event payload.
CREATE INDEX IF NOT EXISTS idx_events_payload_gin ON events USING GIN (payload);

-- 2. B-Tree index on (aggregate_id, version) for fast stream loading.
-- This is crucial for reconstructing aggregate state by loading events in
-- their correct sequence.
CREATE INDEX IF NOT EXISTS idx_events_aggregate_sequence ON events (aggregate_id, version);

-- 3. BRIN index on 'created_at' for efficient range scans by time.
-- This helps in audit log retrieval and provides a foundation for future 
-- table partitioning strategies by date.
CREATE INDEX IF NOT EXISTS idx_events_created_at_brin ON events USING BRIN (created_at);

-- Set comment for clarity
COMMENT ON TABLE events IS 'Immutable transaction log for event sourcing';
COMMENT ON COLUMN events.payload IS 'JSONB event data payload';
COMMENT ON COLUMN events.signature IS 'HMAC-SHA256 signature for data integrity';
COMMENT ON COLUMN events.version IS 'Sequential version number per aggregate for optimistic locking';

COMMIT;

